    },
  }),
  '&:focus-visible': {
    outlineStyle: 'solid',
    outlineWidth: '2px',
    outlineOffset: '1px',
    outlineColor: theme.colors.actionDefaultBorderFocus,
  },
});

const contentStyles = (theme: Theme): Interpolation<Theme> => ({
  ...popoverContentStyles(theme),
});
