  return (
    <div
      ref={ref}
      className={className}
      role="button"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-expanded={isExpanded}
      data-component-id={componentId}
      onClick={(e) => {
        e.stopPropagation();
        onToggle();
      }}
      onKeyDown={handleKeyDown}
      css={{
        position: 'absolute',
        ...positionStyle,
        zIndex: theme.options.zIndexBase - 1,
        width: ROUND_BUTTON_SIZE,
