    <ButtonWithTooltip
      onClick={goToNextStepOrDone}
      disabled={nextButtonDisabled}
      tooltipContent={tooltipContent}
      loading={nextButtonLoading || busyValidatingNextStep}
      type={(extraFooterButtonsRight?.length ?? 0) > 0 ? undefined : 'primary'}
      key="next"
