export interface WizardCurrentStepParams {
  currentStepIndex: number;
  setCurrentStepIndex: (step: number) => void;
  totalSteps: number;
  onValidateStepChange?: (step: number) => Promise<boolean>;
  onStepChanged: ({ step, completed }: { step: number; completed: boolean }) => void;
}

export function useWizardCurrentStep({
  currentStepIndex,
  setCurrentStepIndex,
  totalSteps,
  onValidateStepChange,
  onStepChanged,
}: WizardCurrentStepParams) {
  const [busyValidatingNextStep, setBusyValidatingNextStep] = useState<boolean>(false);
  const isLastStep = useMemo(() => currentStepIndex === totalSteps - 1, [currentStepIndex, totalSteps]);

  const onStepsChange = useCallback(
    async (step: number, completed = false) => {
      if (!completed && step === currentStepIndex) return;

      setCurrentStepIndex(step);
      onStepChanged({ step, completed });
    },
    [currentStepIndex, onStepChanged, setCurrentStepIndex],
  );

  const goToNextStepOrDone = useCallback(async () => {
    if (onValidateStepChange) {
      setBusyValidatingNextStep(true);
      try {
        const approvedStepChange = await onValidateStepChange(currentStepIndex);
        if (!approvedStepChange) {
          return;
        }
      } finally {
        setBusyValidatingNextStep(false);
      }
    }

    onStepsChange(Math.min(currentStepIndex + 1, totalSteps - 1), isLastStep);
  }, [currentStepIndex, isLastStep, onStepsChange, onValidateStepChange, totalSteps]);

  const goToPreviousStep = useCallback(() => {
    if (currentStepIndex > 0) {
      onStepsChange(currentStepIndex - 1);
    }
  }, [currentStepIndex, onStepsChange]);

  const goToStep = useCallback(
    (step: number) => {
      if (step > -1 && step < totalSteps) {
        onStepsChange(step);
      }
    },
    [onStepsChange, totalSteps],
  );

  return {
    busyValidatingNextStep,
    isLastStep,
    onStepsChange,
    goToNextStepOrDone,
    goToPreviousStep,
    goToStep,
  };
}

export type WizardCurrentStepResult = ReturnType<typeof useWizardCurrentStep>;
","import { isUndefined } from 'lodash';
import { useState } from 'react';

import { HorizontalWizardContent } from './HorizontalWizardContent';
import { VerticalWizardContent } from './VerticalWizardContent';
import type { WizardControlledProps, WizardProps } from './WizardProps';
import { useWizardCurrentStep } from './useWizardCurrentStep';

export { MAX_VERTICAL_WIZARD_CONTENT_WIDTH, FIXED_VERTICAL_STEPPER_WIDTH } from './VerticalWizardContent';

export function Wizard({ steps, onStepChanged, onValidateStepChange, initialStep, ...props }: WizardProps) {
  const [currentStepIndex, setCurrentStepIndex] = useState<number>(initialStep ?? 0);
  const currentStepProps = useWizardCurrentStep({
    currentStepIndex,
    setCurrentStepIndex,
    totalSteps: steps.length,
    onStepChanged,
    onValidateStepChange,
  });

  return (
    <WizardControlled
      {...currentStepProps}
      currentStepIndex={currentStepIndex}
      initialStep={initialStep}
      steps={steps}
      onStepChanged={onStepChanged}
      {...props}
    />
  );
}

export function WizardControlled({
  initialStep = 0,
  layout = 'vertical',
  width = '100%',
  height = '100%',
  steps,
  title,
  ...restOfProps
}: WizardControlledProps) {
  if (steps.length === 0 || (!isUndefined(initialStep) && (initialStep < 0 || initialStep >= steps.length))) {
    return null;
  }

  if (layout === 'vertical') {
    return <VerticalWizardContent width={width} height={height} steps={steps} title={title} {...restOfProps} />;
  }

  return <HorizontalWizardContent width={width} height={height} steps={steps} {...restOfProps} />;
}
