import * as Popover from '@radix-ui/react-popover';
import type { ReactElement } from 'react';
import { forwardRef, useCallback, useEffect, useMemo, useRef } from 'react';

import {
  ComponentFinderContext,
  DesignSystemEventProviderAnalyticsEventTypes,
  DesignSystemEventProviderComponentTypes,
  useComponentFinderContext,
  useDesignSystemEventComponentCallbacks,
} from '../DesignSystemEventProvider';
import { useDesignSystemTheme } from '../Hooks';
import { useDesignSystemContext } from '../Hooks/useDesignSystemContext';
import type { AnalyticsEventProps } from '../types';
import { getDarkModePortalStyles, importantify } from '../utils/css-utils';
import { addDebugOutlineIfEnabled } from '../utils/debug';

// WRAPPED RADIX-UI-COMPONENTS
export const Anchor = Popover.Anchor; // Behavioral component only

export type PopoverRootProps = Popover.PopoverProps &
  AnalyticsEventProps<DesignSystemEventProviderAnalyticsEventTypes.OnView>;

export const Root = ({
  children,
  onOpenChange,
  componentId,
  analyticsEvents = [DesignSystemEventProviderAnalyticsEventTypes.OnView],
  ...props
}: PopoverRootProps): ReactElement => {
  const firstView = useRef(true);
  const memoizedAnalyticsEvents = useMemo(() => analyticsEvents, [analyticsEvents]);
  const eventContext = useDesignSystemEventComponentCallbacks({
    componentType: DesignSystemEventProviderComponentTypes.Popover,
    componentId: componentId ?? 'design_system.popover',
    analyticsEvents: memoizedAnalyticsEvents,
  });
  useEffect(() => {
    if (props.open && firstView.current) {
      eventContext.onView();
      firstView.current = false;
    }
  }, [eventContext, props.open]);
  const onOpenChangeHandler = useCallback(
    (open: boolean) => {
      if (open && firstView.current) {
        eventContext.onView();
        firstView.current = false;
      }
      onOpenChange?.(open);
    },
    [eventContext, onOpenChange],
  );
  return (
    <Popover.Root {...props} onOpenChange={onOpenChangeHandler}>
      <ComponentFinderContext.Provider value={{ dataComponentProps: eventContext.dataComponentProps }}>
        {children}
      </ComponentFinderContext.Provider>
    </Popover.Root>
  );
};

export interface PopoverProps extends Popover.PopoverContentProps {
  minWidth?: number;
  maxWidth?: number;
}

export const Content = forwardRef<HTMLDivElement, PopoverProps>(function Content(
  { children, minWidth = 220, maxWidth, ...props },
  ref,
): ReactElement {
  const { getPopupContainer } = useDesignSystemContext();
  const { theme } = useDesignSystemTheme();

  const dataComponentProps = useComponentFinderContext(DesignSystemEventProviderComponentTypes.Popover);

  return (
    <Popover.Portal container={getPopupContainer && getPopupContainer()}>
      <Popover.Content
        {...addDebugOutlineIfEnabled()}
        ref={ref}
        css={[contentStyles(theme), { minWidth, maxWidth }]}
        sideOffset={4}
        aria-label="Popover content"
        {...props}
        {...dataComponentProps}
      >
        {children}
      </Popover.Content>
    </Popover.Portal>
  );
});

export const Trigger = forwardRef<HTMLButtonElement, Popover.PopoverTriggerProps>(function Trigger(
  { children, ...props },
  ref,
): ReactElement {
  return (
    <Popover.Trigger {...addDebugOutlineIfEnabled()} ref={ref} {...props}>
      {children}
    </Popover.Trigger>
  );
});

export const Close = forwardRef<HTMLButtonElement, Popover.PopoverCloseProps>(function Close(
  { children, ...props },
  ref,
): ReactElement {
  return (
    <Popover.Close ref={ref} {...props}>
      {children}
    </Popover.Close>
  );
});

export const Arrow = forwardRef<SVGSVGElement, Popover.PopoverArrowProps>(function Arrow(
  { children, ...props },
  ref,
): ReactElement {
  const { theme } = useDesignSystemTheme();
  return (
    <Popover.Arrow
      css={{
        fill: theme.colors.backgroundPrimary,
        stroke: theme.colors.borderDecorative,
        strokeDashoffset: -CONSTANTS.arrowBottomLength(),
        strokeDasharray: CONSTANTS.arrowBottomLength() + 2 * CONSTANTS.arrowSide(),
        strokeWidth: CONSTANTS.arrowStrokeWidth(),
        // TODO: This is a temporary fix for the alignment of the Arrow;
        // Radix has changed the implementation for v1.0.0 (uses floating-ui)
        // which has new behaviors for alignment that we don't want. Generally
        // we need to fix the arrow to always be aligned to the left of the menu (with
        // offset equal to border radius)
        position: 'relative',
        top: -1,
      }}
      ref={ref}
      width={12}
      height={6}
      {...props}
    >
      {children}
    </Popover.Arrow>
  );
});

// CONSTANTS
const CONSTANTS = {
  arrowBottomLength() {
    // The built in arrow is a polygon: 0,0 30,0 15,10
    return 30;
  },
  arrowHeight() {
    return 10;
  },
  arrowSide() {
    return 2 * (this.arrowHeight() ** 2 * 2) ** 0.5;
  },
  arrowStrokeWidth() {
    // This is eyeballed b/c relative to the svg viewbox coordinate system
    return 2;
  },
};

const popoverContentStyles = (theme: Theme): CSSObject => ({
  backgroundColor: theme.colors.backgroundPrimary,
  color: theme.colors.textPrimary,
  lineHeight: theme.typography.lineHeightBase,
  border: `1px solid ${theme.colors.border}`,
  borderRadius: theme.borders.borderRadiusSm,
  padding: `${theme.spacing.sm}px`,
  boxShadow: theme.shadows.lg,
  zIndex: theme.options.zIndexBase + 30,
  ...getDarkModePortalStyles(theme),
  a: importantify({
    color: theme.colors.actionTertiaryTextDefault,

    '&:hover, &:focus': {
      color: theme.colors.actionTertiaryTextHover,
    },
  }),
  '&:focus-visible': {
    outlineStyle: 'solid',
    outlineWidth: '2px',
    outlineOffset: '1px',
    outlineColor: theme.colors.actionDefaultBorderFocus,
  },
});

const contentStyles = (theme: Theme): Interpolation<Theme> => ({
  ...popoverContentStyles(theme),
});
","import { css } from '@emotion/react';

import { useDesignSystemTheme } from '../Hooks';
import type { HTMLDataAttributes } from '../types';

type validSpacerOptions = 'xs' | 'sm' | 'md' | 'lg';

export interface SpacerProps extends HTMLDataAttributes {
  size?: validSpacerOptions;
  /** Prevents the Spacer component from shrinking when used in flexbox columns. **/
  shrinks?: boolean;
}

export const Spacer: React.FC<React.PropsWithChildren<SpacerProps>> = ({ size = 'md', shrinks, ...props }) => {
  const { theme } = useDesignSystemTheme();

  const spacingValues: Record<validSpacerOptions, number> = {
    xs: theme.spacing.xs,
    sm: theme.spacing.sm,
    md: theme.spacing.md,
    lg: theme.spacing.lg,
  };

  return (
    <div
      css={css({
        height: spacingValues[size],
        ...(shrinks === false ? { flexShrink: 0 } : undefined),
      })}
      {...props}
    />
  );
};
","import { keyframes } from '@emotion/react';

import { ChevronLeftIcon, ChevronRightIcon } from '../Icon';

export function getContentAnimation(width: number) {
  const showAnimation = keyframes`
  from { opacity: 0 }
  80%  { opacity: 0 }
  to   { opacity: 1 }`;
  const openAnimation = keyframes`
  from { width: 50px }
  to   { width: ${width}px }`;

  return {
    open: `${openAnimation} .2s cubic-bezier(0, 0, 0.2, 1)`,
    show: `${showAnimation} .25s linear`,
  };
}

export function getCollapseIcon(position: 'left' | 'right', isExpanded: boolean) {
  if (position === 'right') {
    return isExpanded ? ChevronRightIcon : ChevronLeftIcon;
  }
  return isExpanded ? ChevronLeftIcon : ChevronRightIcon;
}
","import React, { forwardRef, useMemo } from 'react';

import type { CollapseButtonProps } from './types';
import { getCollapseIcon } from './utils';
import { useDesignSystemTheme } from '../Hooks/useDesignSystemTheme';

const ROUND_BUTTON_SIZE = 24;

export const CollapseButton = forwardRef<HTMLDivElement, CollapseButtonProps>(function CollapseButton(
  { isExpanded, position, onToggle, visibility = 'persistent', className, componentId },
  ref,
) {
  const { theme } = useDesignSystemTheme();
  const Icon = getCollapseIcon(position, isExpanded);
  const ariaLabel = isExpanded ? 'hide sidebar' : 'expand sidebar';

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onToggle();
    }
  };

  const positionStyle = useMemo(
    () => ({
      top: '50%',
      transform: 'translateY(-50%)',
      ...(position === 'right' ? { left: -ROUND_BUTTON_SIZE / 2 } : { right: -ROUND_BUTTON_SIZE / 2 }),
    }),
    [position],
  );

  const hiddenByDefault = visibility === 'onHover';

  return (
    <div
      ref={ref}
      className={className}
      role="button"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-expanded={isExpanded}
      data-component-id={componentId}
      onClick={(e) => {
        e.stopPropagation();
        onToggle();
      }}
      onKeyDown={handleKeyDown}
      css={{
        position: 'absolute',
        ...positionStyle,
        zIndex: theme.options.zIndexBase - 1,
        width: ROUND_BUTTON_SIZE,
        height: ROUND_BUTTON_SIZE,
        borderRadius: '50%',
        background: theme.colors.backgroundPrimary,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer',
        boxShadow: `0 0 0 1px ${theme.colors.border}`,
        outline: 'none',
        ...(hiddenByDefault && {
          opacity: 0,
          pointerEvents: 'none' as const,
        }),
        '&:hover': {
          opacity: 1,
          pointerEvents: 'auto',
          boxShadow: `0 0 0 2px ${theme.colors.actionDefaultBorderHover}`,
        },
        '&:focus-visible': {
          opacity: 1,
          pointerEvents: 'auto',
          boxShadow: `0 0 0 2px ${theme.colors.actionDefaultBorderFocus}`,
        },
      }}
    >
      <Icon css={{ fontSize: ROUND_BUTTON_SIZE * 0.75, color: theme.colors.textSecondary }} />
    </div>
  );
});
","import type { ComponentPropsWithoutRef } from 'react';
import { forwardRef } from 'react';

/**
 * `ResizableBox` passes `handleAxis` to the element used as handle. We need to wrap the handle to prevent
 * `handleAxis` becoming an attribute on the div element.
 */
export const ResizablePanelHandle = forwardRef<
  HTMLDivElement,
  {
    handleAxis?: string;
  } & ComponentPropsWithoutRef<'div'>
>(function ResizablePanelHandle({ handleAxis, children, ...otherProps }, ref) {
  return (
    <div ref={ref} {...otherProps}>
      {children}
    </div>
  );
});
